 {drawer.type==='wallet'&&<><h2>{connection?'Your connection':'Bring your voice'}</h2>{connection?<><Badge value="ALLOW">{connection.label}</Badge><p className="address-block">{connection.address}</p><p>Public reads work without a wallet. Disconnecting here does not revoke permissions in your wallet.</p>{connection.localAccount&&<div className="alert notice">Temporary session keys exist only in this tab. Reloading loses signing access. Never send funds to this address.</div>}<button className="button ghost" onClick={()=>{setConnection(null);setDrawer(null)}}><LogOut size={16}/>Disconnect locally</button></>:<><p>Choose your wallet. Your selected provider signs every operation; no replacement account is used.</p>{wallets.map(w=><button className="wallet-option" key={w.id} disabled={busy} onClick={()=>void connectWallet(w)}><Wallet size={20}/>{w.name}<ArrowUpRight size={16}/></button>)}{!wallets.length&&<p className="muted">No injected wallet detected. Open this website in a browser with an EIP-1193 wallet.</p>}<div className="session-box"><h3>Just testing?</h3><p>Create a temporary, faucet-funded Studionet signer. This is a real testnet account, not your browser wallet. It cannot be recovered after reload.</p><button className="button subtle" disabled={busy} onClick={()=>void connectWallet()}>{busy?'Connecting…':'Create testnet session'}<Sprout size={16}/></button></div></>}</>}
 {drawer.type==='activity'&&<><h2>Transaction lifecycle</h2><p>Follow your signed intent through consensus and finalized state.</p><Transactions entries={entries} busy={busy} onRetry={hash=>setEntries(old=>old.map(t=>t.hash===hash?{...t,readback:undefined,error:undefined}:t))}/></>}
 {drawer.type==='evidence'&&proposal&&drawer.value&&(()=>{const m=snap!.edges[drawer.value!],e=proposal.eligibility[drawer.value!];return m&&e?<><h2>Authorization evidence</h2><p>{display(drawer.value!)} → {display(m.to)}</p><Badge value={e.status}/><h3>Signed allowed scope</h3>{m.allow.map((s,i)=><blockquote key={i}>{s}</blockquote>)}<h3>Explicit exclusions</h3>{m.exclude.length?m.exclude.map((s,i)=><blockquote key={i}>{s}<small>Assessment: {e.exclusions?.[i]??'Not reviewed'}</small></blockquote>):<p className="muted">No additional exclusion clauses.</p>}<h3>Proposal anchor</h3><blockquote>{e.proposal_quote??'No accepted scope assessment yet.'}</blockquote><h3>Mandate anchor</h3><blockquote>{e.mandate_quote??'No excerpt yet.'}</blockquote><p>Coverage of the entire proposal: <strong>{e.coverage??'Not assessed'}</strong>. These excerpts are anchors, not a replacement for the complete frozen text.</p><div className="hash-row">Snapshot <code>{proposal.snapshot_hash}</code></div><p className="micro">Source member {short(m.owner)} · mandate version {m.version} · space revision {snap!.space_revision}. Identify this evidence by the full snapshot hash, not the mandate version alone.</p></>:null})()}
 {(drawer.type==='route'||drawer.type==='routes')&&result&&<><h2>{drawer.type==='routes'?'Every voting path':'A voice through the grove'}</h2>{drawer.type==='routes'?<Table r={result}/>:result.routes.filter(r=>r.origin===drawer.value).map(r=><div key={r.origin}><h3>{display(r.origin)}’s original vote</h3><div className="route-steps">{r.path.map((a,i)=><div key={i}><span>{i+1}</span><strong>{display(a)}</strong><code>{short(a)}</code>{snap!.edges[a]&&<button className="text-button" onClick={()=>setDrawer({type:'evidence',value:a})}>View scope<ArrowUpRight size={13}/></button>}</div>)}</div><Badge value={r.choice}/><p>{label(r.reason)}. This path represents exactly one original member’s vote.</p></div>)}</>}
 {drawer.type==='principles'&&<><h2>Trust, with boundaries.</h2><h3>01 · Your mandate, in your words</h3><p>Your allowed scope and exclusions are signed by your wallet. Explicit exclusions win.</p><h3>02 · The whole proposal matters</h3><p>Independent GenLayer validators assess all substantive actions. A label cannot launder an unrelated action into your authorization.</p><h3>03 · Your direct ballot comes first</h3><p>A direct YES, NO or ABSTAIN ends your default delegation on this proposal. Upstream voices may terminate at your direct choice if their paths remain eligible.</p><h3>04 · No voice appears twice</h3><p>Each original member contributes one unit. Cycles, scope barriers and hop limits become visible unexpressed paths.</p></>}
